const regions=window.WINE_REGIONS;const $=id=>document.getElementById(id);const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let selected=null;let map;let regionLayer;let parcelLayer;let wineryLayer;const whiteGrapes=['霞多丽','阿里高特','长相思','赛美蓉','雷司令','白诗南','维尤拉','莫斯卡托','白皮诺','灰皮诺','绿维特利纳','阿尔巴利诺','阿西尔提可','富尔民特','托伦特斯','维欧尼','琼瑶浆','维欧希诺','玛珊','瑚珊','白羽','奇希','甲州','勃艮第香瓜','米勒图高','埃尔布林','卡里坎特','哈斯莱威路','小粒白麝香','阿依达尼','阿斯瑞'];
function sourceLinks(){return '<a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap · 地块、酒庄与地图数据 ↗</a><a href="https://www.bourgogne-wines.com/" target="_blank" rel="noopener">BIVB · 勃艮第葡萄酒行业协会 ↗</a><a href="https://www.wineaustralia.com/" target="_blank" rel="noopener">Wine Australia · 澳大利亚葡萄酒管理局 ↗</a><a href="https://www.nzwine.com/" target="_blank" rel="noopener">New Zealand Wine · 新西兰葡萄酒协会 ↗</a>'}
function matches(r){const q=$('search').value.trim().toLowerCase();return (!$('country').value||r.country===$('country').value)&&(!$('grape').value||r.grapes.includes($('grape').value))&&(!q||[r.name,r.en,r.country,...r.grapes,...r.grapes.map(g=>window.GRAPE_EN[g]||''),...r.wineries.map(w=>w.name+' '+w.en)].join(' ').toLowerCase().includes(q))}
function renderList(){const rs=regions.filter(matches);$('resultCount').textContent=String(rs.length).padStart(2,'0');$('regionList').innerHTML=rs.length?rs.map((r,i)=>`<button class="region-card ${selected===r.id?'selected':''}" data-region="${r.id}" aria-pressed="${selected===r.id}"><span class="number">${String(i+1).padStart(2,'0')}</span><span class="region-copy"><span class="location">${r.continent} / ${r.country}</span><h3>${r.name}</h3><span class="en">${r.en}</span><div class="card-grapes">${r.grapes.slice(0,3).join(' · ')}${r.grapes.length>3?' …':''}</div></span><span class="arrow">↗</span></button>`).join(''):'<div class="empty">没有找到匹配的产区。<br>试试其他名称，或重置筛选。</div>';document.querySelectorAll('[data-region]').forEach(b=>b.onclick=()=>selectRegion(b.dataset.region));if(regionLayer){regionLayer.clearLayers();rs.forEach(r=>{L.circleMarker([r.lat,r.lng],{radius:selected===r.id?10:6,color:'#fff',weight:2,fillColor:'#672c4b',fillOpacity:.9}).addTo(regionLayer).bindTooltip(r.name,{direction:'top',className:'region-label'}).on('click',()=>selectRegion(r.id))})}}
function selectRegion(id){const r=regions.find(r=>r.id===id);if(!r)return;selected=id;renderList();$('mapTitle').textContent=r.name+' · '+r.en;$('mapSubtitle').textContent=r.country+' / '+r.continent;map?.flyTo([r.lat,r.lng],r.zoom,{duration:1.2});$('detail').hidden=false;$('detail').innerHTML=`<div class="detail-top"><button class="detail-close" id="closeDetail" aria-label="关闭产区详情">×</button><div class="eyebrow">${r.country} / ${r.continent}</div><h2>${r.name}</h2><div class="en">${r.en}</div><p class="detail-desc">${r.desc}</p></div><div class="detail-body"><div class="detail-label">主要葡萄品种</div><div class="grapes">${r.grapes.map(g=>`<button class="grape-tag ${whiteGrapes.includes(g)?'white':''}" data-grape="${g}" title="查找种植${g}的产区">${g}</button>`).join('')}</div><div class="detail-section"><div class="detail-label">代表酒庄</div>${r.wineries.length?r.wineries.map(w=>`<div class="winery-item"><a href="${w.url}" target="_blank" rel="noopener">${w.name}<small>${w.en}</small></a><span>↗</span></div>`).join(''):'<p class="detail-note">放大地图，查看公开记录中的附近酒庄。</p>'}</div><p class="detail-note">品种为产区概况，不代表单一地块的实际种植。标记为产区浏览中心。</p><button class="primary" id="exploreParcels">探索葡萄园地块 ↗</button><a class="source-link" target="_blank" rel="noopener" href="${r.source}">产区原始资料 ↗</a></div>`;$('closeDetail').onclick=()=>{$('detail').hidden=true};$('exploreParcels').onclick=()=>{map.flyTo(r.focus||[r.lat,r.lng],14,{duration:1});showStatus('已放大至葡萄园附近，点击“查看此处地块”加载公开轮廓。')};document.querySelectorAll('[data-grape]').forEach(b=>b.onclick=()=>{$('grape').value=b.dataset.grape;renderList()});$('mobileToggle').textContent='浏览产区';document.querySelector('.explorer').classList.remove('open')}
function showStatus(s,error=false){$('mapStatus').hidden=false;$('mapStatus').textContent=s;$('mapStatus').classList.toggle('error',error)}
function init(){[...new Set(regions.map(r=>r.country))].forEach(c=>$('country').add(new Option(c,c)));[...new Set(regions.flatMap(r=>r.grapes))].sort((a,b)=>a.localeCompare(b,'zh-CN')).forEach(g=>$('grape').add(new Option(g,g)));$('coverage').textContent=new Set(regions.map(r=>r.country)).size+' 个国家 · '+regions.length+' 个产区';$('sourceList').innerHTML=sourceLinks();$('search').oninput=renderList;$('country').onchange=renderList;$('grape').onchange=renderList;$('reset').onclick=()=>{$('search').value='';$('country').value='';$('grape').value='';renderList()};$('aboutButton').onclick=()=>$('about').showModal();$('closeAbout').onclick=()=>$('about').close();$('about').onclick=e=>{if(e.target===$('about')){const r=$('about').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('about').close()}};document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();document.querySelector('.explorer').classList.add('open');$('search').focus()}});$('mobileToggle').onclick=()=>{const open=document.querySelector('.explorer').classList.toggle('open');$('mobileToggle').textContent=open?'返回地图':'浏览产区'};renderList();if(!window.L){$('worldButton').disabled=true;$('parcelButton').disabled=true;showStatus('地图资源暂时无法加载。产区资料仍可浏览，请稍后刷新。',true);return}map=L.map('map',{zoomControl:false,minZoom:1,maxZoom:19,worldCopyJump:true}).fitBounds([[-57,-174],[66,178]],{padding:[25,90],maxZoom:3});L.control.zoom({position:'topright'}).addTo(map);map.createPane('baseGeography');map.getPane('baseGeography').style.zIndex=100;fetch('/assets/world.geojson').then(r=>r.json()).then(fc=>L.geoJSON(fc,{pane:'baseGeography',interactive:false,style:{color:'#d0dacb',weight:.6,fillColor:'#f4f5ef',fillOpacity:1}}).addTo(map)).catch(()=>{});map.attributionControl.addAttribution('<a href="https://www.naturalearthdata.com/">Natural Earth</a>');const basemap=L.tileLayer('https://{s}.tile.opentopomap.org/{z}/{x}/{y}.png',{attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> SRTM | <a href="https://opentopomap.org">OpenTopoMap</a> (<a href="https://creativecommons.org/licenses/by-sa/3.0/">CC-BY-SA</a>)',maxNativeZoom:17,maxZoom:19}).addTo(map);let tileFailures=0;basemap.on('tileerror',()=>{if(++tileFailures===5)showStatus('详细底图加载较慢，已保留基础地图；可继续查看产区与已收录地块。')});regionLayer=L.layerGroup().addTo(map);parcelLayer=L.layerGroup().addTo(map);map.on('popupopen',()=>{$('mapStatus').hidden=true});wineryLayer=L.layerGroup().addTo(map);renderList();$('worldButton').onclick=()=>{selected=null;$('detail').hidden=true;$('mapTitle').textContent='世界葡萄酒地图';$('mapSubtitle').textContent='点选一个产区，开启风土之旅';map.flyToBounds([[-57,-174],[66,178]],{padding:[25,90],maxZoom:3,duration:1.3});renderList()};$('parcelButton').onclick=()=>showStatus('请先选择一个产区，并放大至葡萄园周边。')}
init();
